	@Test
	void exhaustiveLivenessKeepsAllReferencedPositionsAndFindsAbsentOwners(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		var config = new LmdbStoreConfig("spoc,posc").setForceSync(true)
				.setInlineLiterals(false)
				.setSketchEstimatorEnabled(false)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false);
		LmdbStore store = new LmdbStore(directory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			var vf = SimpleValueFactory.getInstance();
			IRI subject = vf.createIRI("urn:liveness-control:subject");
			IRI predicate = vf.createIRI("urn:liveness-control:predicate");
			IRI object = vf.createIRI("urn:liveness-control:object");
			IRI context = vf.createIRI("urn:liveness-control:context");
			IRI orphan = vf.createIRI("urn:liveness-control:orphan");
			try (var connection = repository.getConnection()) {
				connection.begin(IsolationLevels.NONE);
				connection.add(subject, predicate, object, context);
				connection.commit();
			}
			ValueStore values = store.getBackingStore().valueStore();
			values.startTransaction(true);
			long orphanId = values.storeValue(orphan);
			values.commit();
			Set<Long> candidates = new HashSet<>(List.of(values.getId(subject), values.getId(predicate),
					values.getId(object), values.getId(context), orphanId));
			store.getBackingStore().getTripleStore().filterUsedIds(candidates);
			assertEquals(Set.of(orphanId), candidates,
					"only a value absent from subject, predicate, object, and context may remain");
		} finally {
			repository.shutDown();
		}
	}

